(() => {
'use strict';
const c=window.HVT,$=s=>document.querySelector(s),esc=c.esc;
let books=[],pages=[],parts=[],book=null,current=null,uid=null,dirty=false,conflict=false,timer=null,pending=null,generation=0,loading=false;
const paper=$('#copyPaper');let richEditing=false;const rich=$('#copyRich')?window.HVTRich.mount($('#copyRich'),{label:'Trang chép của tôi',onChange:()=>{richEditing=true;paper.value=rich.getText();paper.dispatchEvent(new Event('input'));richEditing=false}}):null;
const richHTML=()=>rich?.getHTML()||window.HVTRich.fromText(paper.value);function setPaper(text,html=''){paper.value=text||'';if(rich){if(html)rich.setHTML(html);else rich.setText(text||'')}}
const user=()=>c.currentUser?.()?.id||null;
const key=()=>uid&&book&&current?'hvt-copy:'+uid+':'+book.id+':'+current.page_no:null;
function status(text,error=false){$('#copyStatus').textContent=text;$('#copyStatus').classList.toggle('error',error)}
function remember(){try{if(uid&&book&&current)localStorage.setItem('hvt-copy-last:'+uid,JSON.stringify({book:book.id,page:current.page_no}))}catch{}}
function backup(){try{const k=key();if(k)localStorage.setItem(k,JSON.stringify({...current,content:paper.value,content_html:richHTML(),version:current.version||0}));return true}catch{status('Trình duyệt không lưu được bản khôi phục. Nhấn Lưu trang hoặc tải bản TXT để giữ nội dung.',true);return false}}
function clearBackup(){try{const k=key();if(k)localStorage.removeItem(k)}catch{}}
function controls(){const can=!!(uid&&book&&current&&!loading);paper.disabled=!can;rich?.setDisabled(!can);document.querySelectorAll('[data-copy-output]').forEach(b=>b.disabled=!current);$('#copySave').disabled=!can||conflict;$('#copyNext').disabled=!can||conflict;$('#copyReload').disabled=!can;$('#copyPage').disabled=!uid||loading;$('#copySource').disabled=!book||loading;$('#copyBook').disabled=loading;$('#copyExport').disabled=!current;$('#copyAuthNote').hidden=!!uid;$('#copyCount').textContent=paper.value.length.toLocaleString('vi-VN')+' ký tự';}
function pageOptions(){const entries=[...pages];if(current&&!entries.some(p=>p.page_no===current.page_no))entries.push(current);entries.sort((a,b)=>a.page_no-b.page_no);$('#copyPage').innerHTML=entries.map(p=>`<option value="${p.page_no}">Trang chép ${p.page_no}${p.completed?' · Đã xong':''}</option>`).join('')||'<option>Chưa có trang chép</option>';if(current)$('#copyPage').value=String(current.page_no)}
function sourceTitle(p){return (p.label?p.label+' '+p.number+' · ':'')+'Trang '+(p.page_order||p.number)+(p.title?' — '+p.title:'')}
function sourceFromSelection(){const p=parts.find(p=>p.id===$('#copySource').value);if(p)return{source_section_id:p.id,source_title:sourceTitle(p),source_text:window.HVTRich.text(p.body_html)};return{source_section_id:null,source_title:book?.file_path?'Tài liệu PDF':'Bản văn đầy đủ',source_text:book?.body_html?window.HVTRich.text(book.body_html):book?.body||''}}
function drawSource(){const selected=parts.find(p=>p.id===$('#copySource').value);const host=$('#copyReference');if(current?.source_text&&String(current.source_section_id||'')===String($('#copySource').value||'')){host.textContent=current.source_text}else if(selected){host.innerHTML='<div class="rich-document">'+window.HVTRich.clean(selected.body_html)+'</div>'}else if(current?.source_text){host.textContent=current.source_text}else if(book?.body_html){host.innerHTML='<div class="rich-document">'+window.HVTRich.clean(book.body_html)+'</div>'}else{host.textContent=book?.body||'Tài liệu này chưa có bản văn trực tuyến.'}if(book?.file_path&&!selected){const link=document.createElement('a');link.href=c.publicFile('documents',book.file_path);link.target='_blank';link.rel='noopener noreferrer';link.textContent='Mở bản PDF để đối chiếu ↗';host.append(document.createElement('hr'),link);const note=document.createElement('p');note.className='copy-footnote';note.textContent='PDF mở trong cửa sổ riêng. Chọn bố trí hai cửa sổ trên máy tính để xem cùng trang giấy.';host.append(note)}}
function sourceOptions(){const select=$('#copySource');select.innerHTML=parts.length?parts.map(p=>`<option value="${esc(p.id)}">${esc(sourceTitle(p))}</option>`).join(''):'<option value="">Bản văn đầy đủ / PDF</option>';if(current?.source_section_id&&!parts.some(p=>p.id===current.source_section_id)){const o=document.createElement('option');o.value=current.source_section_id;o.textContent=current.source_title+' · Bản mẫu đã lưu';select.append(o)}if(current)select.value=current.source_section_id||'';drawSource()}
function download(text,name){const blob=new Blob(['\uFEFF'+text],{type:'text/plain;charset=utf-8'}),a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportCurrent(){if(current)download((book?.title||current.resource_title)+'\nTrang chép '+current.page_no+' · '+current.source_title+'\n\n'+paper.value,'Hieu-va-Thuong-Trang-'+current.page_no+'.txt')}
function showRecovery(saved){$('#copyRecovery').hidden=false;$('#copyRecoveryText').value=saved.content||'';$('#copyRecover').onclick=()=>{setPaper(saved.content||'',saved.content_html||'');current={...current,source_section_id:saved.source_section_id,source_title:saved.source_title,source_text:saved.source_text};sourceOptions();dirty=true;conflict=false;$('#copyRecovery').hidden=true;backup();controls();status('Đã đưa bản khôi phục vào trang giấy. Nhấn Lưu trang để lưu trên tài khoản.');};$('#copyRecoveryExport').onclick=()=>download(saved.content||'','Hieu-va-Thuong-Khoi-Phuc.txt')}
async function save(completed=current?.completed||false){
 clearTimeout(timer);if(pending){const ok=await pending;if(!ok)return false;if(!dirty&&completed===current?.completed)return true;return save(completed)}
 if(!current||!uid||user()!==uid||loading||conflict)return false;
 if(paper.value.length>100000||richHTML().length>300000){status('Trang chép quá dài. Tải bản hiện tại về trước khi chia thành các trang ngắn hơn.',true);return false}
 if(!paper.value.trim()&&!current.version){status('Hãy gõ nội dung trước khi lưu trang chép.',true);return false}
 if(!dirty&&current.version&&completed===current.completed)return true;
 const identity=uid,token=generation,snapshot={...current,content:paper.value,content_html:richHTML(),completed};backup();status('Đang lưu trang chép…');
 pending=(async()=>{try{
  const result=await c.api('/rest/v1/rpc/save_transcription_rich_page',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({p_resource_id:book.id,p_page_no:snapshot.page_no,p_source_section_id:snapshot.source_section_id,p_source_title:snapshot.source_title,p_source_text:snapshot.source_text,p_content:snapshot.content,p_completed:completed,p_expected_version:snapshot.version||0,p_content_html:snapshot.content_html})});
  if(identity!==uid||token!==generation||user()!==identity)return false;
  const row=Array.isArray(result)?result[0]:result;if(!row?.version)throw Error('Máy chủ chưa trả về trang đã lưu.');
  const more=richHTML()!==snapshot.content_html||paper.value!==snapshot.content||current.source_section_id!==snapshot.source_section_id||current.source_text!==snapshot.source_text;
  current={...current,content_html:richHTML(),version:row.version,completed:more?current.completed:completed,updated_at:row.updated_at};dirty=more;
  pages=pages.filter(p=>p.page_no!==row.page_no);pages.push(row);pageOptions();remember();
  if(dirty){backup();status('Đã lưu bản trước; đang có thay đổi mới.');timer=setTimeout(()=>save(),1500)}else{clearBackup();status('Đã lưu trên tài khoản lúc '+new Date().toLocaleTimeString('vi-VN',{hour:'2-digit',minute:'2-digit'})+'. Bạn có thể quay lại chép tiếp.');}
  return true;
 }catch(error){if(identity!==uid||token!==generation)return false;const msg=error.message||'';conflict=/thiết bị khác/.test(msg);backup();status(conflict?msg+' Dùng “Tải bản TXT”, sau đó “Tải lại trang đã lưu” để đối chiếu.':/save_transcription_page|schema cache/.test(msg)?'Chưa bật sổ chép. Quản trị cần chạy upgrade-transcription.sql. Bản gõ vẫn được giữ trên trình duyệt nếu bộ nhớ khả dụng.':'Chưa lưu lên tài khoản được. Bản gõ vẫn ở đây. Kiểm tra mạng, đăng nhập lại nếu hết phiên, rồi nhấn Lưu trang.',true);return false}
 finally{pending=null;controls()}})();return pending;
}
async function all(path){let result=[],offset=0;while(true){const rows=await c.api(path+'&limit=1000&offset='+offset);result.push(...rows);if(rows.length<1000)return result;offset+=rows.length}}
async function openPage(number){clearTimeout(timer);loading=true;controls();const token=++generation;try{const rows=await c.api('/rest/v1/transcription_pages?select=*&user_id=eq.'+encodeURIComponent(uid)+'&resource_id=eq.'+encodeURIComponent(book.id)+'&page_no=eq.'+number+'&limit=1');if(token!==generation||uid!==user())return;current=rows[0]||{resource_id:book.id,resource_title:book.title,page_no:number,version:0,completed:false,content:'',...sourceFromSelection()};setPaper(current.content,current.content_html||'');dirty=false;conflict=false;$('#copyRecovery').hidden=true;sourceOptions();pageOptions();remember();status(current.version?'Đã mở trang chép '+number+'. Bạn có thể viết tiếp hoặc chọn trang khác.':'Trang chép mới. Tự lưu sau khi dừng gõ; cũng có thể nhấn Lưu trang.');try{const saved=JSON.parse(localStorage.getItem(key()));if(saved&&(saved.content!==current.content||(saved.content_html||'')!==(current.content_html||'')||saved.source_section_id!==current.source_section_id||saved.source_text!==current.source_text)){if(saved.version===current.version){paper.value=saved.content;current={...current,source_section_id:saved.source_section_id,source_title:saved.source_title,source_text:saved.source_text};dirty=true;sourceOptions();status('Đã khôi phục phần chưa lưu từ trình duyệt. Nhấn Lưu trang để đồng bộ.')}else showRecovery(saved)}}catch{}
 }catch(error){status('Chưa mở được sổ chép. Kiểm tra kết nối và migration upgrade-transcription.sql.',true);current=null;paper.value=''}finally{if(token===generation){loading=false;controls()}}}
async function chooseBook(id,wantedPage){if(dirty&&!(await save())){$('#copyBook').value=book?.id||'';return}loading=true;controls();const token=++generation;const chosen=books.find(b=>b.id===id);if(!chosen){loading=false;controls();return}book=chosen;current=null;setPaper('');try{parts=book.reading_mode==='sections'?await window.HVTSections.publicSections(book.id):[];if(token!==generation)return;sourceOptions();pages=uid?await all('/rest/v1/transcription_pages?select=page_no,version,completed,updated_at,resource_title&user_id=eq.'+encodeURIComponent(uid)+'&resource_id=eq.'+encodeURIComponent(book.id)+'&order=page_no.asc'):[];if(token!==generation)return;loading=false;if(uid){const recent=[...pages].sort((a,b)=>String(b.updated_at).localeCompare(String(a.updated_at)))[0];await openPage(wantedPage||recent?.page_no||1)}else{status('Chọn kinh mẫu để xem. Đăng nhập để bắt đầu sổ chép riêng.');controls()}}catch{loading=false;status('Chưa tải được dữ liệu chép Kinh. Kiểm tra kết nối và chạy upgrade-transcription.sql nếu chưa nâng cấp.',true);controls()}}
async function initialize(){clearTimeout(timer);if(dirty)backup();const initToken=++generation;uid=user();dirty=false;conflict=false;current=null;book=null;pages=[];parts=[];setPaper('');loading=true;controls();try{const library=c.configured===false?[{id:'hvt-practice',kind:'sach',title:'Bài thực hành — bản xem trước',body:'Hôm nay, tôi chậm lại một chút.\n\nLắng nghe để hiểu, hiểu để thương.\n\nBài thực hành do Hiểu và Thương biên soạn, không phải trích kinh.'}]:await c.resources();if(initToken!==generation)return;books=library.filter(b=>['kinh','sach'].includes(b.kind));if(uid){const own=await all('/rest/v1/transcription_pages?select=resource_id,resource_title&user_id=eq.'+encodeURIComponent(uid)+'&order=updated_at.desc');if(initToken!==generation)return;for(const row of own)if(!books.some(b=>b.id===row.resource_id))books.push({id:row.resource_id,title:row.resource_title+' · Bản mẫu đã gỡ',kind:'kinh',reading_mode:'single'});}$('#copyBook').innerHTML=books.map(b=>`<option value="${esc(b.id)}">${esc(b.title)}</option>`).join('')||'<option value="">Thư viện chưa có Kinh/Sách</option>';let last=null;try{last=JSON.parse(localStorage.getItem('hvt-copy-last:'+uid))}catch{}const requested=new URLSearchParams(location.search).get('book');const chosen=books.find(b=>b.id===(requested||last?.book))||books[0];loading=false;if(chosen){$('#copyBook').value=chosen.id;await chooseBook(chosen.id,last?.book===chosen.id?last.page:undefined)}else status('Kinh và Sách công khai sẽ xuất hiện ở đây khi được thêm vào thư viện.')}catch{loading=false;status('Chưa tải được sổ chép. Nếu vừa cập nhật V7, cần chạy upgrade-transcription.sql trong Supabase trước.',true);controls()}}
paper.addEventListener('input',()=>{if(!current)return;if(!richEditing)rich?.setText(paper.value);dirty=true;current.completed=false;backup();controls();status(conflict?'Trang có bản sửa từ thiết bị khác. Tải TXT trước khi đối chiếu.':'Chưa đồng bộ thay đổi mới · đang giữ bản khôi phục trên trình duyệt.');clearTimeout(timer);if(!conflict)timer=setTimeout(()=>save(),1500)});
$('#copySave').onclick=()=>save();$('#copyExport').onclick=exportCurrent;
$('#copyNext').onclick=async()=>{if(!(await save(true)))return;const next=Math.max(current.page_no,...pages.map(p=>p.page_no))+1;if(next>99999){status('Đã đạt giới hạn trang.',true);return}const n=parts.findIndex(p=>p.id===current.source_section_id);if(n>=0&&n<parts.length-1)$('#copySource').value=parts[n+1].id;await openPage(next);if(rich)rich.focus();else paper.focus()};
$('#copyBook').onchange=e=>chooseBook(e.target.value);$('#copyPage').onchange=async e=>{const number=Number(e.target.value);if(dirty&&!(await save())){e.target.value=String(current.page_no);return}await openPage(number)};
$('#copySource').onchange=()=>{drawSource();if(current){current={...current,...sourceFromSelection()};dirty=true;backup();if(paper.value.trim())timer=setTimeout(()=>save(),1500)}};
$('#copyLayout').onchange=e=>{$('#copyGrid').classList.toggle('stacked',e.target.value==='stacked');try{localStorage.setItem('hvt-copy-layout',e.target.value)}catch{}};try{$('#copyLayout').value=localStorage.getItem('hvt-copy-layout')||'side';$('#copyLayout').onchange({target:$('#copyLayout')})}catch{}
$('#copyReload').onclick=async()=>{if(dirty&&!window.confirm('Bản chưa đồng bộ sẽ được giữ trong phần khôi phục. Bạn nên tải TXT trước. Mở bản mới nhất trên máy chủ?'))return;if(dirty)backup();dirty=false;conflict=false;await openPage(current.page_no)};
$('#copyLogin').onclick=()=>$('#accountBtn').click();
window.addEventListener('beforeunload',e=>{if(dirty){backup();e.preventDefault();e.returnValue=''}});window.addEventListener('pagehide',()=>{if(dirty)backup()});window.addEventListener('online',()=>{if(dirty&&!conflict)save()});
for(const event of ['hvt-auth-change','hvt-auth-lost'])window.addEventListener(event,()=>{initialize()});
window.HVTCopyPage={snapshot:()=>current?{title:book?.title||current.resource_title,page:current.page_no,source:current.source_title,html:richHTML(),text:paper.value}:null};
initialize();
})();
